'use strict';
const METHOD_GALLERY={
 'zh-Hant':{intro:'點選一種麻醉方式，展開簡單介紹。實際照護可能合併不同方式，會由麻醉團隊和你討論。',items:[['全身麻醉','讓意識暫時消失，藥物可經點滴或吸入給予。麻醉團隊會持續照顧你的呼吸、疼痛與身體狀況。'],['靜脈麻醉','藥物由點滴進入，依處置調整清醒或睡眠程度。靜脈給藥也可用於全身麻醉，名稱與實際深度需和團隊確認。'],['半身麻醉','通常在背部注射局部麻醉藥，讓下半身暫時麻木，常用於下腹或腿部手術；需要時可搭配鎮靜。'],['神經阻斷術','在特定神經附近給予局部麻醉藥，讓對應部位暫時減少疼痛。可單獨使用或配合其他麻醉方式。']]},
 en:{intro:'Tap a method for a short introduction. Your care may combine methods; discuss the plan with your anesthesia team.',items:[['General anesthesia','Medicines temporarily make you unconscious. They may be given through an IV or inhaled. Your team looks after breathing, pain and body functions.'],['Intravenous anesthesia','Medicines enter through an IV, with awareness adjusted for the procedure. IV medicines can also provide general anesthesia; confirm the intended depth with your team.'],['Spinal anesthesia','Local anesthetic is usually injected in the back to numb the lower body temporarily. It is used for some lower-body operations and may be combined with sedation.'],['Nerve block','Local anesthetic near a specific nerve temporarily reduces pain in the area it supplies. It may be used alone or alongside other anesthesia methods.']]},
 id:{intro:'Ketuk satu metode untuk membaca penjelasan singkat. Beberapa metode dapat digabungkan; diskusikan rencananya dengan tim anestesi.',items:[['Anestesi umum','Obat membuatmu tidak sadar untuk sementara. Obat dapat diberikan melalui infus atau dihirup. Tim menjaga pernapasan, nyeri, dan fungsi tubuh.'],['Anestesi intravena','Obat masuk melalui infus, dengan tingkat kesadaran disesuaikan dengan tindakan. Obat infus juga dapat digunakan untuk anestesi umum; pastikan rencananya dengan tim.'],['Anestesi spinal','Obat bius lokal biasanya disuntikkan di punggung untuk membuat tubuh bagian bawah mati rasa sementara. Pada beberapa operasi dapat digabungkan dengan sedasi.'],['Blok saraf','Obat bius lokal di dekat saraf tertentu membantu mengurangi nyeri sementara di area terkait. Bisa digunakan sendiri atau bersama metode anestesi lain.']]},
 th:{intro:'แตะวิธีที่ต้องการเพื่ออ่านคำอธิบายสั้น ๆ อาจใช้หลายวิธีร่วมกัน โปรดพูดคุยแผนกับทีมวิสัญญี',items:[['ดมยาสลบ','ยาอาจให้ทางสายน้ำเกลือหรือสูดดม เพื่อให้หมดสติชั่วคราว ทีมจะดูแลการหายใจ ความปวด และการทำงานของร่างกาย'],['ให้ยาระงับความรู้สึกทางหลอดเลือดดำ','ให้ยาทางสายน้ำเกลือ ปรับระดับความรู้สึกตัวตามหัตถการ ยาทางหลอดเลือดดำอาจใช้ดมยาสลบได้ด้วย ควรถามทีมถึงระดับที่วางแผนไว้'],['บล็อกหลัง','มักฉีดยาชาที่หลังให้ร่างกายส่วนล่างชาชั่วคราว ใช้กับการผ่าตัดส่วนล่างบางชนิด และอาจให้ยาระงับประสาทร่วมด้วย'],['บล็อกเส้นประสาท','ให้ยาชาใกล้เส้นประสาทเฉพาะจุด เพื่อลดปวดในบริเวณที่เส้นประสาทนั้นเลี้ยงชั่วคราว อาจใช้เดี่ยวหรือร่วมกับวิธีอื่น']]},
 vi:{intro:'Chạm vào một phương pháp để xem giới thiệu ngắn. Có thể phối hợp các phương pháp; hãy trao đổi kế hoạch với đội ngũ gây mê.',items:[['Gây mê toàn thân','Thuốc làm mất ý thức tạm thời, có thể qua đường truyền hoặc hít. Đội ngũ chăm sóc hô hấp, cơn đau và chức năng cơ thể.'],['Gây mê qua đường tĩnh mạch','Thuốc qua đường truyền, điều chỉnh mức tỉnh theo thủ thuật. Thuốc tĩnh mạch cũng có thể dùng để gây mê toàn thân; cần xác nhận mức dự kiến với đội ngũ.'],['Gây tê tủy sống','Thường tiêm thuốc tê ở lưng để làm tê tạm thời phần dưới cơ thể. Dùng cho một số phẫu thuật phần dưới, có thể phối hợp an thần.'],['Phong bế thần kinh','Thuốc tê gần một dây thần kinh giúp giảm đau tạm thời vùng tương ứng. Có thể dùng riêng hoặc phối hợp phương pháp gây mê khác.']]},
 fil:{intro:'Pindutin ang isang paraan para sa maikling paliwanag. Maaaring pagsamahin ang mga paraan; pag-usapan ang plano sa pangkat ng anesthesia.',items:[['General anesthesia','Pansamantalang nawawala ang kamalayan sa gamot na ibinibigay sa suwero o nilalanghap. Inaalagaan ng pangkat ang paghinga, sakit at paggana ng katawan.'],['Intravenous anesthesia','Ibinibigay ang gamot sa suwero at inaangkop ang kamalayan sa pamamaraan. Maaari ring gamitin ang gamot sa suwero para sa general anesthesia; itanong ang planong antas.'],['Spinal anesthesia','Karaniwang itinuturok sa likod ang pampamanhid upang pansamantalang mamanhid ang ibabang katawan. Para sa ilang operasyon, maaari itong sabayan ng sedation.'],['Nerve block','Pampamanhid malapit sa isang nerbiyos upang pansamantalang mabawasan ang sakit sa kaugnay na bahagi. Maaaring mag-isa o kasama ng ibang paraan ng anesthesia.']]}
};
function renderMethodGallery(root){const data=METHOD_GALLERY[language];root.innerHTML=`<div class="station-chip">${esc(t('station',{n:2}))}</div><h2 id="topic-title">${esc(topicName(1))}</h2><p class="method-intro">${esc(data.intro)}</p><div class="method-accordion"></div>`;data.items.forEach(([title,body],i)=>{const details=document.createElement('details');details.name='anesthesia-method';details.className='method-detail';const summary=document.createElement('summary');summary.innerHTML=`<span class="method-number">0${i+1}</span><span>${esc(title)}</span><span class="method-plus" aria-hidden="true">＋</span>`;details.append(summary,textElement('p',body));root.querySelector('.method-accordion').append(details)});const plan=document.createElement('fieldset');plan.className='method-plan';plan.innerHTML=`<legend>${esc(catalogUI().plan)} · ${esc(surgeryName())}</legend><p>${esc(patient?.surgery==='GI01'?UPPER_GI_DEFAULT[language]:catalogUI().defaultNote)}</p>${data.items.map(([title],index)=>`<label><input type="radio" name="gallery-method" value="${[0,2,1,4][index]}" ${careState.method===[0,2,1,4][index]?'checked':''}>${esc(title)}</label>`).join('')}`;plan.querySelectorAll('input').forEach(input=>input.onchange=()=>careState.method=Number(input.value));root.querySelector('.method-accordion').before(plan);renderCatalog(root);const back=textElement('button',t('backMap'),'primary');back.onclick=()=>$('#topic-dialog').close();root.append(back);const refs=document.createElement('details');refs.className='care-sources';refs.append(textElement('summary',t('sources')));[['General anesthesia','https://www.nhs.uk/tests-and-treatments/general-anaesthesia/'],['Intravenous sedation','https://rcoa.ac.uk/patients/patient-information-resources/patient-information-leaflets-video-resources/sedation-explained'],['Spinal anesthesia','https://rcoa.ac.uk/patients/patient-information-resources/patient-information-leaflets-video-resources/your-spinal-anaesthetic'],['Nerve block','https://www.rcoa.ac.uk/patients/patient-information-resources/patient-information-leaflets-video-resources/peripheral-nerve-blocks']].forEach(([title,url])=>{const a=textElement('a',title+' ↗');a.href=url;a.target='_blank';a.rel='noopener';refs.append(a)});root.append(refs);}
